package docker

import (
	"context"
	"fmt"
	"time"
)

// DockerExecConfig holds configuration for executing commands in a Docker container.
type DockerExecConfig struct {
	Image              string
	CWD                string
	Timeout            time.Duration
	Env                map[string]string
	EnvAllowlist       []string
	ContainerName      string
	WorkspacePath      string
	ContainerWorkspace string
}

// DockerExecResult holds the captured output of a Docker exec command.
type DockerExecResult struct {
	Stdout   string
	Stderr   string
	ExitCode int
	Duration time.Duration
}

// DockerRunner abstracts Docker container execution for testability.
type DockerRunner interface {
	Run(ctx context.Context, image string, cmd []string, env map[string]string,
		mounts []MountEntry, cwd string, timeout time.Duration) (DockerExecResult, error)
}

// DockerExecBackend executes commands inside Docker containers with mount
// policy enforcement, image resolution, env filtering, and timeout cleanup.
type DockerExecBackend struct {
	runner DockerRunner
	config DockerExecConfig
	policy MountPolicy
}

// NewDockerExecBackend creates a backend backed by the given runner.
func NewDockerExecBackend(runner DockerRunner, config DockerExecConfig, hostPaths []string) *DockerExecBackend {
	return &DockerExecBackend{
		runner: runner,
		config: config,
		policy: DefaultMountPolicy(hostPaths),
	}
}

// resolveImage returns the configured image or a Hermes-compatible default.
func (b *DockerExecBackend) resolveImage() string {
	if b.config.Image != "" {
		return b.config.Image
	}
	return "hermes-sandbox:latest"
}

// filteredEnv returns only allowlisted environment variables.
func (b *DockerExecBackend) filteredEnv() map[string]string {
	return filterEnvSnapshot(b.config.Env, b.config.EnvAllowlist)
}

func filterEnvSnapshot(env map[string]string, allowlist []string) map[string]string {
	if len(allowlist) == 0 {
		return copyEnv(env)
	}
	filtered := make(map[string]string, len(allowlist))
	for _, key := range allowlist {
		if val, ok := env[key]; ok {
			filtered[key] = val
		}
	}
	return filtered
}

func copyEnv(env map[string]string) map[string]string {
	if env == nil {
		return nil
	}
	copied := make(map[string]string, len(env))
	for key, val := range env {
		copied[key] = val
	}
	return copied
}

// Execute runs a command inside a Docker container with mount policy,
// image resolution, env filtering, and timeout.
func (b *DockerExecBackend) Execute(ctx context.Context, command string, args []string) (DockerExecResult, error) {
	mounts := b.policy.AllowedMounts(b.config.WorkspacePath, b.config.ContainerWorkspace)

	cwd := b.config.CWD
	if cwd == "" {
		cwd = containerWorkspacePath(b.config.ContainerWorkspace)
	}

	timeout := b.config.Timeout
	if timeout == 0 {
		timeout = 60 * time.Second
	}

	image := b.resolveImage()
	env := b.filteredEnv()

	ctxWithTimeout, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()

	cmd := append([]string{command}, args...)
	result, err := b.runner.Run(ctxWithTimeout, image, cmd, env, mounts, cwd, timeout)
	if err != nil {
		return result, fmt.Errorf("docker exec: %w", err)
	}

	return result, nil
}

package docker

import "strings"

// DockerContainerRequest describes the task scope used to key a Docker
// execution environment before the live Docker backend exists.
type DockerContainerRequest struct {
	TaskID     string
	IsSubagent bool
	IsRollout  bool
}

// DockerContainerKey returns the reusable Docker container key for a request.
func DockerContainerKey(req DockerContainerRequest) string {
	taskID := strings.TrimSpace(req.TaskID)
	if taskID != "" {
		return taskID
	}
	if req.IsSubagent || req.IsRollout {
		return ""
	}
	return "default"
}

package docker

import (
	"path/filepath"
	"strings"
)

const defaultContainerWorkspace = "/workspace"

// MountPolicy defines allowed and blocked host paths for Docker mounts.
type MountPolicy struct {
	AllowedHostPaths []string
	BlockedPrefixes  []string
}

// MountEntry describes a resolved mount from host to container.
type MountEntry struct {
	HostPath      string
	ContainerPath string
	ReadOnly      bool
}

// DefaultMountPolicy returns a policy that blocks dangerous system paths
// and Docker socket access while allowing configured host paths.
func DefaultMountPolicy(hostPaths []string) MountPolicy {
	return MountPolicy{
		AllowedHostPaths: hostPaths,
		BlockedPrefixes: []string{
			"/etc/",
			"/proc/",
			"/sys/",
			"/var/run/docker.sock",
		},
	}
}

// IsBlocked reports whether a host path matches any blocked prefix.
func (p MountPolicy) IsBlocked(hostPath string) bool {
	clean, ok := normalizeMountHostPath(hostPath)
	if !ok {
		return false
	}
	for _, prefix := range p.BlockedPrefixes {
		if blockedPrefixMatches(clean, prefix) {
			return true
		}
	}
	return false
}

func normalizeMountHostPath(hostPath string) (string, bool) {
	clean := filepath.Clean(strings.TrimSpace(hostPath))
	if clean == "." || !filepath.IsAbs(clean) {
		return "", false
	}
	return clean, true
}

func blockedPrefixMatches(cleanHostPath, rawPrefix string) bool {
	cleanPrefix := filepath.Clean(strings.TrimSpace(rawPrefix))
	if cleanPrefix == "." {
		return false
	}
	return cleanHostPath == cleanPrefix || strings.HasPrefix(cleanHostPath, cleanPrefix+string(filepath.Separator))
}

// IsAllowed reports whether a host path is both in the allowlist and not blocked.
func (p MountPolicy) IsAllowed(hostPath string) bool {
	clean, ok := normalizeMountHostPath(hostPath)
	if !ok || p.IsBlocked(clean) {
		return false
	}
	for _, allowed := range p.AllowedHostPaths {
		allowedClean, ok := normalizeMountHostPath(allowed)
		if ok && clean == allowedClean {
			return true
		}
	}
	return false
}

// AllowedMounts returns the resolved mount entries for allowed host paths.
// Workspace paths (typically the working directory) are mapped read-write;
// other allowed paths are mapped read-only.
func (p MountPolicy) AllowedMounts(workspacePath, containerWorkspace string) []MountEntry {
	var mounts []MountEntry
	seen := map[string]struct{}{}
	workspaceHost, _ := normalizeMountHostPath(workspacePath)
	workspace := mountWorkspace{hostPath: workspaceHost, containerPath: containerWorkspacePath(containerWorkspace)}
	for _, hostPath := range p.AllowedHostPaths {
		candidate := p.classifyMountCandidate(hostPath, workspace)
		if !candidate.allowed {
			continue
		}
		if _, ok := seen[candidate.entry.HostPath]; ok {
			continue
		}
		seen[candidate.entry.HostPath] = struct{}{}
		mounts = append(mounts, candidate.entry)
	}
	return mounts
}

type mountWorkspace struct {
	hostPath      string
	containerPath string
}

type mountCandidate struct {
	entry   MountEntry
	allowed bool
	blocked bool
}

func (p MountPolicy) classifyMountCandidate(hostPath string, workspace mountWorkspace) mountCandidate {
	cleanHost, ok := normalizeMountHostPath(hostPath)
	if !ok {
		return mountCandidate{}
	}
	if p.IsBlocked(cleanHost) {
		return mountCandidate{blocked: true}
	}
	readOnly := true
	containerPath := cleanHost
	if cleanHost == workspace.hostPath {
		readOnly = false
		containerPath = workspace.containerPath
	}
	return mountCandidate{
		entry: MountEntry{
			HostPath:      cleanHost,
			ContainerPath: containerPath,
			ReadOnly:      readOnly,
		},
		allowed: true,
	}
}

func containerWorkspacePath(containerWorkspace string) string {
	clean := filepath.Clean(strings.TrimSpace(containerWorkspace))
	if clean == "." || !strings.HasPrefix(clean, "/") {
		return defaultContainerWorkspace
	}
	return clean
}

