	t.Run("passes env snapshot when no allowlist", func(t *testing.T) {
		runner := &fakeDockerRunner{
			result: DockerExecResult{Stdout: "ok", ExitCode: 0},
		}
		backend := NewDockerExecBackend(runner, DockerExecConfig{
